package com.opensocket.aievent.core.issuetracking.core;
import com.opensocket.aievent.core.issuetracking.recovery.*;
public final class ProjectionBackpressurePolicy { public ProjectionLaneStatus laneStatus(int queueDepth,int maxQueueDepth,ProviderHealthStatus health){if(health==ProviderHealthStatus.DISABLED)return ProjectionLaneStatus.DISABLED;if(health==ProviderHealthStatus.OPEN_CIRCUIT)return ProjectionLaneStatus.OPEN_CIRCUIT;if(queueDepth>=maxQueueDepth)return ProjectionLaneStatus.SATURATED;if(health==ProviderHealthStatus.THROTTLED)return ProjectionLaneStatus.THROTTLED;if(health==ProviderHealthStatus.RECOVERING)return ProjectionLaneStatus.RECOVERING;return ProjectionLaneStatus.ACTIVE;} public boolean reject(int queueDepth,int maxQueueDepth,ProjectionOperationType operation){return queueDepth>=maxQueueDepth&&operation!=ProjectionOperationType.CLOSE;} }
